public effect Check
  /// Fails the test when `actual = expected` is false.
  function equal[T: equality](actual: T, expected: T) -> Unit
  /// Fails the test when `actual = expected` is true.
  function notEqual[T: equality](actual: T, expected: T) -> Unit
  /// Fails the test with `message` when `condition` is false.
  function isTrue(condition: Boolean, message: String) -> Unit
  /// Fails the test with `message`. It does not return.
  function fail[T](message: String) -> T
end effect

public data ByteOrder
  /// The most significant byte first.
  BigEndian
  /// The least significant byte first.
  LittleEndian
end data

public effect Time
  /// Stops the calling task for at least `milliseconds` while other tasks run. Returns at once for 0 or less.
  function sleep(milliseconds: Integer) -> Unit
  /// Returns milliseconds from an unspecified start. The value never decreases within a run.
  function monotonicMilliseconds() -> Integer
  /// Returns the current time.
  function now() -> TimeValue.Instant
  /// Returns the difference of local time from UTC in minutes, east positive. Returns 0 when it is unknown.
  function localOffsetMinutes() -> Integer
end effect

public effect Write
  /// Writes `text` to standard output.
  function write(text: String) -> Unit
  /// Writes `text` and a line feed to standard output.
  function writeLine(text: String) -> Unit
  /// Writes `text` to standard error.
  function writeError(text: String) -> Unit
  /// Writes `text` and a line feed to standard error.
  function writeErrorLine(text: String) -> Unit
end effect

public effect Read
  /// Reads one line. Returns `Option.None` at the end of the input.
  function readLine() -> Result[Option[String], IOError]
  /// Reads the rest of the input.
  function readAll() -> Result[String, IOError]
  /// Reads the rest of the input and splits it into lines.
  function readAllLines() -> Result[List[String], IOError]
  /// Reads the rest of the input as bytes.
  function readAllBytes() -> Result[Bytes, IOError]
end effect

public effect Read
  /// Reads the whole file as text. Fails with `IOErrorKind.InvalidUTF8` when the content is not UTF-8.
  function readText(path: String) -> Result[String, IOError]
  /// Opens the file for reading line by line.
  function openReader(path: String) -> Result[Reader, IOError]
  /// Reads one line. Returns `Option.None` at the end of the file.
  function readLine(reader: Reader) -> Result[Option[String], IOError]
  /// Reads the whole file as bytes.
  function readBytes(path: String) -> Result[Bytes, IOError]
  /// Reads the whole file as text and splits it into lines.
  function readLines(path: String) -> Result[List[String], IOError]
  /// Returns whether something exists at the path. Fails when it cannot be checked.
  function exists(path: String) -> Result[Boolean, IOError]
  /// Returns information about the file. A symbolic link itself is described, not its target.
  function info(path: String) -> Result[Info, IOError]
  /// Returns the names in the directory, ordered by their UTF-8 bytes.
  function listDirectory(path: String) -> Result[List[String], IOError]
  /// Returns every file and directory under the directory as relative paths, ordered by their UTF-8 bytes.
  function walk(path: String) -> Result[List[String], IOError]
  /// Returns the absolute path with symbolic links resolved.
  function canonicalize(path: String) -> Result[String, IOError]
  /// Reads at most `maximumBytes` bytes. Returns `Option.None` at the end of the file.
  function readChunk(reader: Reader, maximumBytes: Integer) -> Result[Option[Bytes], IOError]
end effect

public effect Write
  /// Creates or replaces the file with `text`.
  function writeText(path: String, text: String) -> Result[Unit, IOError]
  /// Adds `text` to the end of the file, creating it when missing.
  function appendText(path: String, text: String) -> Result[Unit, IOError]
  /// Creates or replaces the file with `content`.
  function writeBytes(path: String, content: Bytes) -> Result[Unit, IOError]
  /// Adds `content` to the end of the file, creating it when missing.
  function appendBytes(path: String, content: Bytes) -> Result[Unit, IOError]
  /// Creates the directory and any missing parents. Does nothing when the directory exists.
  function createDirectory(path: String) -> Result[Unit, IOError]
  /// Removes a file, a symbolic link, or an empty directory.
  function remove(path: String) -> Result[Unit, IOError]
  /// Removes the directory and everything under it. Symbolic links are removed, not followed.
  function removeTree(path: String) -> Result[Unit, IOError]
  /// Moves `from` to `to`.
  function rename(from: String, to: String) -> Result[Unit, IOError]
  /// Opens the file for writing. `WriteMode.Replace` creates or empties it; `WriteMode.Append` adds to its end.
  function openWriter(path: String, mode: WriteMode) -> Result[Writer, IOError]
  /// Writes `text`.
  /// After a write fails, returns the same error without writing anything.
  function write(writer: Writer, text: String) -> Result[Unit, IOError]
  /// Writes `text` and a line feed.
  /// After a write fails, returns the same error without writing anything.
  function writeLine(writer: Writer, text: String) -> Result[Unit, IOError]
  /// Writes `content`.
  /// After a write fails, returns the same error without writing anything.
  function writeChunk(writer: Writer, content: Bytes) -> Result[Unit, IOError]
end effect

public data WriteMode
  /// Create the file or empty it.
  Replace
  /// Add to the end of the file, creating it when missing.
  Append
end data

public effect Environment
  /// Returns the command-line arguments given to the script.
  function arguments() -> List[String]
  /// Returns the absolute path of the directory of the script that started the run.
  function scriptDirectory() -> String
  /// Returns the value of the environment variable, or `Option.None` when it is not defined.
  function environmentVariable(name: String) -> Result[Option[String], IOError]
  /// Returns the absolute path of the working directory.
  function workingDirectory() -> Result[String, IOError]
end effect

public effect Run
  /// Starts the command without a shell, waits for it, and returns its exit code and output.
  /// Returns Result.Error with IOErrorKind.InvalidInput before starting a child or arranging its pipes if Command.environment explicitly sets a name starting with DYLD_ or LD_ (ASCII case-insensitive).
  /// This includes LD_RUN_PATH used by build tools, lowercase names, empty values, and resetting the same inherited value, on every OS.
  /// Existing invalid-input checks (NUL, empty names, and `=` in names) take precedence. The error names the first forbidden variable in lexical order of the original names, without its value.
  /// Inherited variables are unchanged. Allowing Process.Run still permits env or a shell to set variables itself; this rule does not isolate child processes or control PATH, grandchildren, or every Windows DLL search.
  function run(command: Command) -> Result[Output, IOError]
  /// Starts the command with the standard streams of the script, waits for it, and returns its exit code.
  /// Rejects explicit DYLD_ and LD_ settings with IOErrorKind.InvalidInput before starting a child, with the same ASCII case-insensitive rules and error ordering as run, including LD_RUN_PATH, empty values, and same-value overwrites; inherited variables are unchanged.
  function runAttached(command: Command) -> Result[Integer, IOError]
  /// Runs `commandLine` with `/bin/sh -c` and returns the result as `run` does. Write only POSIX sh.
  /// Inherits the parent's environment unchanged. The Command.environment input rule does not prevent a shell command from setting loader variables; enforce isolation in the harness or OS.
  function shell(commandLine: String) -> Result[Output, IOError]
end effect

public effect Generate
  /// Returns an integer from `low` up to, but not including, `high`. Stops the program when `high` is not greater than `low`.
  function integer(low: Integer, high: Integer) -> Integer
  /// Returns a number from 0.0 up to, but not including, 1.0.
  function float() -> Float
  /// Returns `true` or `false`.
  function boolean() -> Boolean
  /// Returns the elements in a random order.
  function shuffle[T](xs: List[T]) -> List[T]
  /// Returns a random element, or `Option.None` when the list is empty.
  function choose[T](xs: List[T]) -> Option[T]
end effect

@extensible
public data IOErrorKind
  /// The path or the command does not exist.
  NotFound
  /// The operating system refused the operation.
  PermissionDenied
  /// The thing to create already exists.
  AlreadyExists
  /// A directory was given where a file is needed.
  IsDirectory
  /// Something other than a directory was given where a directory is needed.
  NotDirectory
  /// A non-empty directory was given where an empty one is needed.
  DirectoryNotEmpty
  /// The content read is not valid UTF-8.
  InvalidUTF8
  /// An argument cannot be passed to the operating system, such as a path containing NUL.
  InvalidInput
  /// None of the above.
  Other
end data

public effect Log
  /// Sends one event to the selected handler.
  function emit(record: Record) -> Unit
  /// Asks whether the selected handler accepts this level.
  function enabled(level: Level) -> Benitoite.Boolean
end effect

public effect Listen
  /// Starts listening on `port` of `host`. Port 0 lets the operating system choose a free port.
  function listen(host: String, port: Integer) -> Result[Listener, NetworkError]
  /// Returns the port the listener listens on.
  function listenerPort(listener: Listener) -> Integer
  /// Waits for the next request and accepts it. Other tasks run while it waits.
  function accept(listener: Listener) -> Result[Exchange, NetworkError]
  /// Sends the response. Stops the program when called twice for one exchange.
  /// The status must be between 200 and 599. Sends no body for HEAD requests,
  /// statuses 204, 205, and 304, or 2xx responses to CONNECT requests.
  function respond(exchange: Exchange, response: Response) -> Result[Unit, NetworkError]
end effect

@extensible
public data NetworkErrorKind
  /// The name cannot be resolved.
  HostNotFound
  /// The connection was refused.
  ConnectionRefused
  /// The connection was cut in the middle.
  ConnectionReset
  /// The time ran out.
  TimedOut
  /// The address and port to listen on are in use.
  AddressInUse
  /// What was received is not valid HTTP.
  InvalidHTTPData
  /// A URL or an address is not in a valid form.
  InvalidInput
  /// The operating system refused the operation.
  PermissionDenied
  /// None of the above, including a failed TLS certificate check.
  Other
end data

public data RoundingMode
  /// The nearest value; halves go to the value whose last digit is even.
  HalfToEven
  /// The nearest value; halves go away from zero.
  HalfAwayFromZero
  /// Toward zero.
  TowardZero
  /// Toward negative infinity.
  TowardNegativeInfinity
  /// Toward positive infinity.
  TowardPositiveInfinity
end data

public trait Applicative[F[_]: Functor]
  /// Wraps `x`.
  function pure[A](x: A) -> F[A]
  /// Applies the functions in `fs` to the values in `x`.
  function apply[A, B, effect E](fs: F[function(value: A) -> B uses E], x: F[A]) -> F[B] uses E
end trait

public trait Applicative2[F[_, _]: Functor2]
  /// Wraps `x`. Annotate the result when its second type cannot be inferred.
  function pure[A, X](x: A) -> F[A, X]
  /// Applies the wrapped function to `x`; the Result implementation prefers an error in `fs`.
  function apply[A, B, X, effect E](fs: F[(function(value: A) -> B uses E), X], x: F[A, X]) -> F[B, X] uses E
end trait
